import{_t as e,it as t,n,rt as r}from"./chunks/framework.BIpRff3v.js";var i=JSON.parse(`{"title":"Conventions","description":"","frontmatter":{},"headers":[],"relativePath":"conventions.md","filePath":"conventions.md"}`),a={name:`conventions.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="conventions" tabindex="-1" dir="auto">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to “Conventions”">​</a></h1><h2 id="naming" tabindex="-1" dir="auto">Naming <a class="header-anchor" href="#naming" aria-label="Permalink to “Naming”">​</a></h2><table tabindex="0"><thead><tr><th dir="auto">Thing</th><th dir="auto">Convention</th><th dir="auto">Example</th></tr></thead><tbody><tr><td dir="auto">Folders, projects</td><td dir="auto">kebab-case; Nx project name = folder name</td><td dir="auto"><code>apps/site</code>, project <code>site</code></td></tr><tr><td dir="auto">Shared util libs</td><td dir="auto"><code>libs/shared/&lt;name&gt;</code>, project <code>shared-&lt;name&gt;</code></td><td dir="auto"><code>libs/shared/utils</code> → <code>shared-utils</code></td></tr><tr><td dir="auto">Other libs</td><td dir="auto"><code>libs/&lt;name&gt;</code></td><td dir="auto"><code>libs/booking</code></td></tr><tr><td dir="auto">Import paths</td><td dir="auto"><code>@starter/&lt;project&gt;</code></td><td dir="auto"><code>@starter/ui</code>, <code>@starter/shared-utils</code></td></tr><tr><td dir="auto">Components</td><td dir="auto">PascalCase file + named export, in a kebab-case folder</td><td dir="auto"><code>src/lib/date-picker/DatePicker.tsx</code></td></tr><tr><td dir="auto">Tests / stories</td><td dir="auto">next to the file: <code>Name.spec.tsx</code>, <code>Name.stories.tsx</code></td><td dir="auto"></td></tr><tr><td dir="auto">Pages</td><td dir="auto"><code>src/pages/&lt;Name&gt;Page.tsx</code></td><td dir="auto"><code>HomePage.tsx</code></td></tr><tr><td dir="auto">Spikes</td><td dir="auto"><code>apps/sandbox/src/spikes/&lt;yyyy-mm&gt;-&lt;slug&gt;/{meta.ts,index.tsx}</code></td><td dir="auto"><code>2026-09-hebrew-fonts</code></td></tr><tr><td dir="auto">ADRs</td><td dir="auto"><code>docs/decisions/NNNN-short-title.md</code></td><td dir="auto"><code>0004-use-zustand.md</code></td></tr></tbody></table><p dir="auto">Prefer named exports. Default exports exist only where a tool requires them (Storybook meta, lazy-loaded spikes).</p><h2 id="tags-module-boundaries" tabindex="-1" dir="auto">Tags (module boundaries) <a class="header-anchor" href="#tags-module-boundaries" aria-label="Permalink to “Tags (module boundaries)”">​</a></h2><p dir="auto">Every project has one <code>type:*</code> and one <code>scope:*</code> tag in <code>package.json</code> → <code>nx.tags</code>.</p><table tabindex="0"><thead><tr><th dir="auto">Tag</th><th dir="auto">Meaning</th><th dir="auto">May depend on</th></tr></thead><tbody><tr><td dir="auto"><code>type:app</code></td><td dir="auto">deployable app</td><td dir="auto">feature, ui, util</td></tr><tr><td dir="auto"><code>type:e2e</code></td><td dir="auto">Playwright project</td><td dir="auto">util</td></tr><tr><td dir="auto"><code>type:feature</code></td><td dir="auto">React + logic (pages, state, data)</td><td dir="auto">feature, ui, util</td></tr><tr><td dir="auto"><code>type:ui</code></td><td dir="auto">presentational React components</td><td dir="auto">ui, util</td></tr><tr><td dir="auto"><code>type:util</code></td><td dir="auto">framework-free TypeScript</td><td dir="auto">util</td></tr><tr><td dir="auto"><code>type:tooling</code></td><td dir="auto">build/dev tooling (<code>tools/*</code>)</td><td dir="auto">(not imported by app code)</td></tr><tr><td dir="auto"><code>scope:product</code></td><td dir="auto">ships to users</td><td dir="auto">product, shared</td></tr><tr><td dir="auto"><code>scope:dev</code></td><td dir="auto">internal helpers (sandbox, ...)</td><td dir="auto">dev, shared, product</td></tr><tr><td dir="auto"><code>scope:shared</code></td><td dir="auto">usable by everyone</td><td dir="auto">shared</td></tr></tbody></table><p dir="auto">The rules live in the root <code>eslint.config.mjs</code> (<code>@nx/enforce-module-boundaries</code>).</p><h2 id="sandbox-spikes" tabindex="-1" dir="auto">Sandbox spikes <a class="header-anchor" href="#sandbox-spikes" aria-label="Permalink to “Sandbox spikes”">​</a></h2><p dir="auto">A spike answers <strong>one question</strong> quickly and then goes away.</p><table tabindex="0"><thead><tr><th dir="auto">Stage</th><th dir="auto">What happens</th></tr></thead><tbody><tr><td dir="auto">Create</td><td dir="auto"><code>pnpm new:spike &lt;slug&gt;</code> creates <code>src/spikes/&lt;yyyy-mm&gt;-&lt;slug&gt;/meta.ts</code> (title + the question, in <code>description</code>) and <code>index.tsx</code> (the experiment). It appears on the sandbox index automatically. Reusing a slug is an error.</td></tr><tr><td dir="auto">Run</td><td dir="auto"><code>pnpm nx dev sandbox</code> (<a href="http://localhost:4201" target="_blank" rel="noreferrer">http://localhost:4201</a>). Each spike is lazy-loaded in its own chunk; the build fails if one lands in the main chunk.</td></tr><tr><td dir="auto">Verify</td><td dir="auto">Spikes are linted (including the RTL rule), typechecked and built by <code>pnpm verify</code>. They need no tests. A spike that doesn&#39;t compile is fixed or deleted, never excluded.</td></tr><tr><td dir="auto">Promote</td><td dir="auto">The question was answered with &quot;yes&quot;: move the code into a lib or app (<code>pnpm new:lib</code>, <code>pnpm new:component</code>), then delete the spike.</td></tr><tr><td dir="auto">Delete</td><td dir="auto">Remove the folder. Nothing else references it; <code>verify</code> stays green even with zero spikes.</td></tr></tbody></table><p dir="auto">Rules: nothing imports from the sandbox (module boundaries enforce it), and the sandbox is never deployed.</p><p dir="auto">Projects that don&#39;t want a sandbox remove it with <code>pnpm nx g @nx/workspace:remove sandbox</code>. <code>pnpm new:spike</code> then fails with a clear &quot;No sandbox app&quot; message.</p><h2 id="rtl" tabindex="-1" dir="auto">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to “RTL”">​</a></h2><ul><li dir="auto"><code>dir</code>/<code>lang</code> are set per app in <code>index.html</code>. Libraries never assume a direction.</li><li dir="auto">Logical utilities only. ESLint (<code>no-restricted-syntax</code> in the root config) rejects physical ones: <code>ml/mr/pl/pr/left/right-*</code>, <code>text-left/right</code>, <code>rounded-l/r</code>, <code>border-l/r</code>, <code>float-left/right</code>.</li><li dir="auto">Storybook defaults to RTL; flip the <strong>Direction</strong> toolbar to check LTR.</li></ul><h2 id="dependencies" tabindex="-1" dir="auto">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h2><ul><li dir="auto">Dependabot opens the update PRs (see <code>.github/dependabot.yml</code>). It bumps <code>nx</code> / <code>@nx/*</code> versions but never runs <code>nx migrate</code>. Nx minors ride in the <code>npm-minor-patch</code> group; majors get their own <code>nx</code> group PR.</li><li dir="auto">For any Nx bump that has migrations (always check majors), don&#39;t merge the Dependabot PR as is. Locally run <code>pnpm nx migrate &lt;version&gt;</code>, <code>pnpm install</code> and <code>pnpm nx migrate --run-migrations</code>, then <code>pnpm verify</code>. Delete <code>migrations.json</code> and open one PR with the result; close the Dependabot PR.</li><li dir="auto">Use the exact syntax from the Nx docs for the installed Nx major; check <code>pnpm nx migrate --help</code> and don&#39;t guess flags.</li></ul><h2 id="dead-code" tabindex="-1" dir="auto">Dead code <a class="header-anchor" href="#dead-code" aria-label="Permalink to “Dead code”">​</a></h2><p dir="auto"><code>knip</code> runs in <code>pnpm verify</code> and CI. Unused files, exports, types and dependencies fail it. Don&#39;t export a symbol just in case; export it when something imports it. If code is used without an import knip can follow (a workflow script, a hook, a generator loaded by Nx), teach knip in <code>knip.ts</code> with an <code>entry</code> and a one-line reason. Don&#39;t ignore a whole folder.</p><h2 id="git" tabindex="-1" dir="auto">Git <a class="header-anchor" href="#git" aria-label="Permalink to “Git”">​</a></h2><ul><li dir="auto">Small commits with an imperative subject line in English (&quot;Add booking form&quot;).</li><li dir="auto"><code>main</code> is always deployable; it deploys to Pages on every push.</li></ul>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};